// Four more calm, instrumental pieces for the playlist (piece 1, the original theme, stays in ambient-music.mjs).
// All of it is generated by the same toolkit as the original (detuned pads, soft plucks and bells, a generated
// reverb): original music, nothing sampled or downloaded. Each piece is plain data (key, tempo, chords, voices,
// patterns); one planner and one voice bank play them.

const midiToHz = midi => 440 * 2 ** ((midi - 69) / 12);
const between = (random, min, max) => min + (max - min) * random();

