export const PIECE_BY_ID = Object.fromEntries(PIECES.map(piece => [piece.id, piece]));

export function createPiecePlan(piece, random = Math.random) {
  const beat = 60 / piece.bpm;
  return {
    piece,
    random,
    beat,
    chordAt: 0,
    chordIndex: -1,
    timeline: [],
    patternAt: 0,
    patternStep: 0,
    leadAt: piece.lead ? piece.lead.first * beat : Infinity,
    leadIndex: piece.lead ? Math.floor(piece.lead.scale.length / 2) : 0
  };
}

// Moves the cursors to `time` or later; the pattern restarts with the next chord.
export function catchUpPiece(plan, time) {
  if (plan.chordAt < time) plan.chordAt = time;
  if (plan.patternAt < plan.chordAt && plan.piece.pattern) {
    plan.patternAt = plan.chordAt;
    plan.patternStep = 0;
  }
  if (plan.leadAt < time) plan.leadAt = time + (plan.piece.lead ? plan.piece.lead.first * plan.beat : 0);
}

const chordTone = (notes, index, octave) =>
  notes[index % notes.length] + 12 * Math.floor(index / notes.length) + octave;

// The chord changes up to `stop`, each remembered on the timeline the pattern reads.
function planChords(plan, stop, events) {
  const { piece, random, beat } = plan;
  while (plan.chordAt < stop) {
    plan.chordIndex = (plan.chordIndex + 1) % piece.chords.length;
    const length = piece.chordBeats * beat,
      notes = piece.chords[plan.chordIndex];
    events.push({
      type: 'chord',
      at: plan.chordAt,
      length,
      notes,
      variation: piece.id,
      cutoff: between(random, piece.pad.cutoff[0], piece.pad.cutoff[1])
    });
    plan.timeline.push({ at: plan.chordAt, end: plan.chordAt + length, notes });
    plan.chordAt += length;
  }
}
// The broken-chord pattern up to `stop`, on the tones of the chord sounding at each step.
function planPattern(plan, stop, events) {
  const { random, beat } = plan,
    { pattern } = plan.piece,
    stepLength = pattern.stepBeats * beat;
  while (plan.patternAt < stop) {
    const chord = plan.timeline.find(c => c.at <= plan.patternAt + 1e-6 && plan.patternAt < c.end - 1e-6);
    if (!chord) {
      plan.patternAt = plan.chordAt;
      break;
    }
    const index = Math.round((plan.patternAt - chord.at) / stepLength),
      tone = pattern.steps[index % pattern.steps.length];
    if (tone !== null && random() >= pattern.skip) {
      const accent = index % pattern.steps.length === 0 ? 1 : between(random, 0.6, 0.9);
      events.push({
        type: 'note',
        voice: pattern.voice,
        at: plan.patternAt,
        midi: chordTone(chord.notes, tone, pattern.octave),
        level: accent,
        side: random() < 0.5 ? 0 : 1
      });
    }
    plan.patternAt += stepLength;
  }
}
// The slow lead up to `stop`: a random walk on its scale.
function planLead(plan, stop, events) {
  const { random, beat } = plan,
    { lead } = plan.piece;
  while (plan.leadAt < stop) {
    const step = lead.steps[Math.floor(random() * lead.steps.length)];
    plan.leadIndex = Math.min(lead.scale.length - 1, Math.max(0, plan.leadIndex + step));
    events.push({
      type: 'note',
      voice: lead.voice,
      at: plan.leadAt,
      midi: lead.scale[plan.leadIndex],
      hold: between(random, lead.holdBeats[0], lead.holdBeats[1]) * beat,
      level: between(random, 0.6, 1),
      side: random() < 0.5 ? 0 : 1
    });
    plan.leadAt += between(random, lead.gapBeats[0], lead.gapBeats[1]) * beat;
  }
}
// Events that start before `horizon` (and before `limit`, the piece's own end), in time order.
export function planPieceUntil(plan, horizon, limit = Infinity) {
  const stop = Math.min(horizon, limit),
    events = [];
  planChords(plan, stop, events);
  if (plan.piece.pattern) planPattern(plan, stop, events);
  if (plan.piece.lead) planLead(plan, stop, events);
  // Chords that are over are not needed for the pattern any more.
  while (plan.timeline.length > 2 && plan.timeline[0].end < plan.patternAt - 1) plan.timeline.shift();
  return events.sort((a, b) => a.at - b.at);
}

function sidePanner(ctx, pan, targets) {
  const node = ctx.createStereoPanner ? ctx.createStereoPanner() : ctx.createGain();
  if ('pan' in node) node.pan.value = pan;
  for (const target of targets) node.connect(target);
  return node;
}

// The voice bank of one piece; same shape as createVoices() of the original (`play`, `master`).
// Every gain ramps from and to zero. `impulseResponse(ctx, seconds, decay, random)` makes the reverb tail.
export function createPieceVoices(ctx, piece, random, output, impulseResponse) {
  const { pad, reverb } = piece;
  const master = ctx.createGain();
  master.gain.value = piece.trim ?? 1;
  master.connect(output);
  const dry = ctx.createGain();
  dry.gain.value = reverb.dry;
  dry.connect(master);
  const wet = ctx.createGain();
  wet.gain.value = reverb.wet;
  const convolver = ctx.createConvolver();
  convolver.buffer = impulseResponse(ctx, reverb.seconds, reverb.decay, random);
  wet.connect(convolver);
  convolver.connect(master);
  const padFilter = ctx.createBiquadFilter();
  padFilter.type = 'lowpass';
  padFilter.frequency.value = pad.cutoff[0];
  padFilter.Q.value = pad.q;
  padFilter.connect(dry);
  padFilter.connect(wet);
  const padSides = [-pad.spread, pad.spread].map(pan => sidePanner(ctx, pan, [padFilter]));
  const noteSides = [-0.35, 0.35].map(pan => sidePanner(ctx, pan, [dry, wet]));

  const startOf = event => Math.max(event.at, ctx.currentTime + 0.05);
  const tone = (type, hz, detune, target, start, stop) => {
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.value = hz;
    osc.detune.value = detune;
    osc.connect(target);
    osc.start(start);
    osc.stop(stop);
    return osc;
  };
  function playChord(event) {
    const start = startOf(event),
      hold = start + event.length,
      end = hold + pad.release;
    padFilter.frequency.setTargetAtTime(event.cutoff, start, pad.attack);
    padSides.forEach((side, index) => {
      const envelope = ctx.createGain();
      envelope.gain.setValueAtTime(0, start);
      envelope.gain.linearRampToValueAtTime(pad.level, start + pad.attack);
      envelope.gain.setValueAtTime(pad.level, hold);
      envelope.gain.linearRampToValueAtTime(0, end);
      envelope.connect(side);
      const detune = (index ? 1 : -1) * pad.detune;
      /** @type {OscillatorNode | null} */
      let last = null;
      event.notes.forEach((midi, i) => {
        pad.waves.forEach((wave, w) => {
          last = tone(wave, midiToHz(midi), detune * (w ? -0.5 : 1), envelope, start, end + 0.05);
        });
        // A soft octave-down root under the lowest note.
        if (pad.sub && i === 0) {
          const sub = ctx.createGain();
          sub.gain.value = pad.sub;
          sub.connect(envelope);
          last = tone('sine', midiToHz(midi - 12), 0, sub, start, end + 0.05);
        }
      });
      if (last) last.onended = () => envelope.disconnect();
    });
  }
  function playNote(event) {
    const voice = piece.voices[event.voice],
      start = startOf(event),
      hz = midiToHz(event.midi),
      level = voice.level * (event.level ?? 1),
      envelope = ctx.createGain();
    let end;
    if (voice.sustain) {
      // A soft breath of a note: slow attack, hold, slow release.
      const hold = start + Math.max(voice.attack + 0.1, event.hold ?? 1);
      end = hold + voice.release;
      envelope.gain.setValueAtTime(0, start);
      envelope.gain.linearRampToValueAtTime(level, start + voice.attack);
      envelope.gain.setValueAtTime(level, hold);
      envelope.gain.linearRampToValueAtTime(0, end);
    } else {
      end = start + voice.decay;
      envelope.gain.setValueAtTime(0, start);
      envelope.gain.linearRampToValueAtTime(level, start + voice.attack);
      envelope.gain.exponentialRampToValueAtTime(0.0001, end);
      envelope.gain.linearRampToValueAtTime(0, end + 0.05);
    }
    let out = envelope;
    let filter = null;
    if (voice.bright) {
      // A plucked string loses its brightness as it rings.
      filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.Q.value = 0.5;
      filter.frequency.setValueAtTime(Math.min(5000, hz * voice.bright), start);
      filter.frequency.exponentialRampToValueAtTime(Math.max(300, hz * 1.2), start + voice.decay * 0.5);
      envelope.connect(filter);
      out = filter;
    }
    out.connect(noteSides[event.side ?? 0]);
    if (voice.overtone) {
      const overtone = ctx.createGain(),
        until = start + (voice.overtoneDecay ?? 0.4);
      overtone.gain.setValueAtTime(0, start);
      overtone.gain.linearRampToValueAtTime(voice.overtoneLevel, start + voice.attack);
      if (voice.sustain) overtone.gain.setValueAtTime(voice.overtoneLevel, end - voice.release);
      overtone.gain.exponentialRampToValueAtTime(0.0001, voice.sustain ? end : until);
      overtone.gain.linearRampToValueAtTime(0, (voice.sustain ? end : until) + 0.02);
      overtone.connect(envelope);
      tone('sine', hz * voice.overtone, 0, overtone, start, (voice.sustain ? end : until) + 0.05);
    }
    const main = tone(voice.wave, hz, 0, envelope, start, end + 0.1);
    if (voice.vibrato) {
      // Slow vibrato that blooms after the attack.
      const lfo = ctx.createOscillator(),
        depth = ctx.createGain();
      lfo.frequency.value = voice.vibratoHz ?? 5;
      depth.gain.setValueAtTime(0, start);
      depth.gain.linearRampToValueAtTime(voice.vibrato, start + 0.9);
      lfo.connect(depth);
      depth.connect(main.detune);
      lfo.start(start);
      lfo.stop(end + 0.1);
    }
    main.onended = () => {
      envelope.disconnect();
      filter?.disconnect();
    };
  }
  return {
    master,
    play(event) {
      if (event.type === 'chord') playChord(event);
      else playNote(event);
    },
    dispose() {
      master.disconnect();
    }
  };
}
